/**
 * Python string/bytes primitives that the port relies on.
 *
 * Python treats a `str` as a sequence of code points while JavaScript treats a
 * string as a sequence of UTF-16 code units.  Every routine in this project
 * that needs Python indexing/slicing semantics goes through `toCodePoints`.
 */

/** Split a JS string into an array of code points (Python `list(s)`). */
export function toCodePoints(s) {
  const out = [];
  for (let i = 0; i < s.length; i++) {
    const c = s.codePointAt(i);
    out.push(c);
    if (c > 0xffff) i++;
  }
  return out;
}

/** Number of code points in `s` (Python `len(s)`). */
export function pyLen(s) {
  return toCodePoints(s).length;
}

/** Rebuild a string from an array of code points. */
export function fromCodePoints(cps) {
  let out = '';
  for (const cp of cps) out += String.fromCodePoint(cp);
  return out;
}

/** Encode a JS string to a Latin-1/ASCII byte array, or null when impossible. */
export function encodeAscii(s) {
  const cps = toCodePoints(s);
  const out = new Uint8Array(cps.length);
  for (let i = 0; i < cps.length; i++) {
    if (cps[i] > 0x7f) return null; // UnicodeEncodeError in Python
    out[i] = cps[i];
  }
  return out;
}

/** Decode an ASCII byte array back into a JS string. */
export function decodeAscii(bytes) {
  let out = '';
  for (const b of bytes) out += String.fromCharCode(b);
  return out;
}

/** `bytes.lower()` restricted to ASCII, as Python's bytes type does. */
export function bytesLower(bytes) {
  const out = new Uint8Array(bytes.length);
  for (let i = 0; i < bytes.length; i++) {
    const b = bytes[i];
    out[i] = b >= 0x41 && b <= 0x5a ? b + 0x20 : b;
  }
  return out;
}

/** True when `bytes` begins with `prefix`. */
export function bytesStartsWith(bytes, prefix) {
  if (bytes.length < prefix.length) return false;
  for (let i = 0; i < prefix.length; i++) {
    if (bytes[i] !== prefix[i]) return false;
  }
  return true;
}

/** Concatenate byte arrays. */
export function bytesConcat(...parts) {
  let total = 0;
  for (const p of parts) total += p.length;
  const out = new Uint8Array(total);
  let off = 0;
  for (const p of parts) {
    out.set(p, off);
    off += p.length;
  }
  return out;
}

/** Turn an ASCII JS string into bytes (callers guarantee ASCII). */
export function asciiBytes(s) {
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

