/**
 * Faithful re-implementation of CPython's `repr()` for `str` and `bytes`.
 *
 * idna embeds `repr(label)` inside most of its error messages, so the escaping
 * rules have to match character for character (Python uses lower-case hex in
 * `\x`/`\u`/`\U` escapes and picks the quote character based on the content).
 */

import { toCodePoints } from './pystr.mjs';

// str.isprintable(): false for Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs -- except U+0020.
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

function isPrintable(cp) {
  if (cp === 0x20) return true;
  return !NON_PRINTABLE.test(String.fromCodePoint(cp));
}

function hex(value, width) {
  return value.toString(16).padStart(width, '0');
}

/** CPython `repr(some_str)`. */
export function reprStr(s) {
  const cps = toCodePoints(s);
  // Python prefers single quotes, switching to double quotes only when the
  // string contains a single quote but no double quote.
  let quote = 0x27;
  if (cps.includes(0x27) && !cps.includes(0x22)) quote = 0x22;

  let out = String.fromCharCode(quote);
  for (const cp of cps) {
    if (cp === quote || cp === 0x5c) {
      out += '\\' + String.fromCharCode(cp);
    } else if (cp === 0x09) {
      out += '\\t';
    } else if (cp === 0x0a) {
      out += '\\n';
    } else if (cp === 0x0d) {
      out += '\\r';
    } else if (cp < 0x20 || cp === 0x7f) {
      out += '\\x' + hex(cp, 2);
    } else if (cp < 0x7f) {
      out += String.fromCodePoint(cp);
    } else if (isPrintable(cp)) {
      out += String.fromCodePoint(cp);
    } else if (cp < 0x100) {
      out += '\\x' + hex(cp, 2);
    } else if (cp < 0x10000) {
      out += '\\u' + hex(cp, 4);
    } else {
      out += '\\U' + hex(cp, 8);
    }
  }
  return out + String.fromCharCode(quote);
}

/** CPython `repr(some_bytes)` -- e.g. `b'xn--rsum-bpad.com'`. */
export function reprBytes(bytes) {
  let quote = 0x27;
  if (bytes.includes(0x27) && !bytes.includes(0x22)) quote = 0x22;

  let out = 'b' + String.fromCharCode(quote);
  for (const b of bytes) {
    if (b === quote || b === 0x5c) {
      out += '\\' + String.fromCharCode(b);
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b < 0x20 || b >= 0x7f) {
      out += '\\x' + hex(b, 2);
    } else {
      out += String.fromCharCode(b);
    }
  }
  return out + String.fromCharCode(quote);
}

/** idna's `_unot()` helper: `U+00DF`. */
export function unot(cp) {
  return 'U+' + cp.toString(16).toUpperCase().padStart(4, '0');
}

