/**
 * Unicode character property queries.
 *
 * Node ships a full Unicode character database inside its regular-engine, so
 * the properties RFC 5892 needs (general category, `Changes_When_NFKC_
 * Casefolded`, `Default_Ignorable_Code_Point`, ...) are queried through Unicode
 * property escapes instead of being shipped as generated tables.
 */

const cache = new Map();

function tester(pattern) {
  const re = new RegExp(`^${pattern}$`, 'u');
  return (cp) => {
    let byCp = cache.get(pattern);
    if (byCp === undefined) {
      byCp = new Map();
      cache.set(pattern, byCp);
    }
    let hit = byCp.get(cp);
    if (hit === undefined) {
      hit = re.test(String.fromCodePoint(cp));
      byCp.set(cp, hit);
    }
    return hit;
  };
}

// --- General categories -----------------------------------------------------
export const isLu = tester('\\p{Lu}');
export const isLl = tester('\\p{Ll}');
export const isLo = tester('\\p{Lo}');
export const isLm = tester('\\p{Lm}');
export const isNd = tester('\\p{Nd}');
export const isMn = tester('\\p{Mn}');
export const isMc = tester('\\p{Mc}');
export const isMe = tester('\\p{Me}');
export const isCn = tester('\\p{Cn}');

/** Python `unicodedata.category(ch)[0] == 'M'`. */
export function isMark(cp) {
  return isMn(cp) || isMc(cp) || isMe(cp);
}

// --- Binary properties ------------------------------------------------------
/** RFC 5892 "Unstable": NFKC_Casefold(cp) != cp. */
export const changesWhenNfkcCasefolded = tester('\\p{Changes_When_NFKC_Casefolded}');
export const isDefaultIgnorable = tester('\\p{Default_Ignorable_Code_Point}');
export const isWhiteSpace = tester('\\p{White_Space}');
export const isNoncharacter = tester('\\p{Noncharacter_Code_Point}');

// --- Scripts (used by the CONTEXTO rules) -----------------------------------
const SCRIPT_TESTERS = {
  Greek: tester('\\p{Script=Greek}'),
  Han: tester('\\p{Script=Han}'),
  Hebrew: tester('\\p{Script=Hebrew}'),
  Hiragana: tester('\\p{Script=Hiragana}'),
  Katakana: tester('\\p{Script=Katakana}'),
};

/** idna's `_is_script(cp, script)`. */
export function isScript(cp, script) {
  const test = SCRIPT_TESTERS[script];
  return test ? test(cp) : false;
}

/** Binary search over a flat sorted [lo, hi, lo, hi, ...] range table. */
export function inRanges(cp, ranges) {
  let lo = 0;
  let hi = ranges.length / 2 - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (cp < ranges[mid * 2]) hi = mid - 1;
    else if (cp > ranges[mid * 2 + 1]) lo = mid + 1;
    else return true;
  }
  return false;
}

