import { execFile } from 'node:child_process';

const EXE = '/workspace/dataset/test8_executable';
const ZWNJ = '‌';
const RTL_D = 'ب'; // ARABIC LETTER BEH (dual joining)
const LTR_D = 'ᠠ'; // MONGOLIAN LETTER A (dual joining)

const RANGES = [
  [0x0620, 0x06ff], [0x0700, 0x074f], [0x0750, 0x077f], [0x07c0, 0x07ff],
  [0x0840, 0x085f], [0x0860, 0x088f], [0x08a0, 0x08ff],
  [0x1800, 0x18af], [0xa840, 0xa873],
  [0x10ac0, 0x10aef], [0x10b80, 0x10baf], [0x10d00, 0x10d3f],
  [0x10f30, 0x10f6f], [0x10f70, 0x10faf], [0x10fb0, 0x10fdf],
  [0x1e900, 0x1e95f],
];

const isRTL = (cp) => !((cp >= 0x1800 && cp <= 0x18af) || (cp >= 0xa840 && cp <= 0xa873));
const skip = (cp) => /^[\p{Mn}\p{Me}\p{Cf}\p{Cn}]$/u.test(String.fromCodePoint(cp));

function run(domain) {
  return new Promise((resolve) => {
    execFile(EXE, ['--domain', domain, '--mode', 'decode'], { encoding: 'utf8' }, (e, stdout) => {
      resolve(stdout);
    });
  });
}

const candidates = [];
for (const [lo, hi] of RANGES) {
  for (let cp = lo; cp <= hi; cp++) {
    if (skip(cp)) continue;
    const ch = String.fromCodePoint(cp);
    if (ch.normalize('NFC') !== ch) continue;
    candidates.push(cp);
  }
}
process.stderr.write(`candidates: ${candidates.length}\n`);

async function pool(items, worker, size) {
  const out = new Array(items.length);
  let idx = 0;
  await Promise.all(Array.from({ length: size }, async () => {
    while (idx < items.length) {
      const i = idx++;
      out[i] = await worker(items[i]);
    }
  }));
  return out;
}

const results = await pool(candidates, async (cp) => {
  const ch = String.fromCodePoint(cp);
  const comp = isRTL(cp) ? RTL_D : LTR_D;
  const [a, b] = await Promise.all([
    run(ch + ZWNJ + comp),   // ok => cp is L or D (satisfies the "before" scan)
    run(comp + ZWNJ + ch),   // ok => cp is R or D (satisfies the "after" scan)
  ]);
  return { cp, before: !a.includes('decode_error'), after: !b.includes('decode_error'), a, b };
}, 16);

const types = {};
for (const r of results) {
  // A disallowed codepoint fails both probes for the wrong reason; ignore those.
  const bogus = r.a.includes('at position 1 of') || r.b.includes('at position 3 of');
  let t;
  if (r.before && r.after) t = 'D';
  else if (r.before) t = 'L';
  else if (r.after) t = 'R';
  else t = bogus ? '?' : 'U';
  types[r.cp] = t;
}

const lines = [];
let start = null, cur = null;
const cps = Object.keys(types).map(Number).sort((x, y) => x - y);
for (let i = 0; i < cps.length; i++) {
  const cp = cps[i];
  const t = types[cp];
  if (cur !== t || (start !== null && cp !== cps[i - 1] + 1)) {
    if (start !== null) lines.push([start, cps[i - 1], cur]);
    start = cp; cur = t;
  }
}
if (start !== null) lines.push([start, cps[cps.length - 1], cur]);

process.stdout.write(JSON.stringify(lines) + '\n');

