  [0x302f, DISALLOWED], [0x3031, DISALLOWED], [0x3032, DISALLOWED],
  [0x3033, DISALLOWED], [0x3034, DISALLOWED], [0x3035, DISALLOWED],
  [0x303b, DISALLOWED],
