/**
 * Bidi_Class lookup and the RFC 5893 Bidi Rule check.
 *
 * Node's regular-expression engine does not expose Bidi_Class, so the class is
 * reconstructed from the block defaults published in DerivedBidiClass.txt plus
 * the derivations that cover every code point IDNA can actually reach (all
 * marks are NSM, digits follow their block, everything else defaults to L).
 */

import { isMn, isMe, isCn, inRanges } from './unicodeprops.mjs';
import { toCodePoints } from './pystr.mjs';
import { reprStr } from './pyrepr.mjs';
import { IDNABidiError } from './errors.mjs';

// DerivedBidiClass.txt @missing block defaults.
const R_BLOCKS = [
  0x0590, 0x05ff, 0x07c0, 0x085f, 0xfb1d, 0xfb4f,
  0x10800, 0x10cff, 0x10d40, 0x10ebf, 0x10f00, 0x10f2f, 0x10f70, 0x10fff,
  0x1e800, 0x1ec6f, 0x1ed50, 0x1edff, 0x1ef00, 0x1efff,
];
const AL_BLOCKS = [
  0x0600, 0x07bf, 0x0860, 0x08ff, 0xfb50, 0xfdcf, 0xfdf0, 0xfdff, 0xfe70, 0xfeff,
  0x10d00, 0x10d3f, 0x10ec0, 0x10eff, 0x10f30, 0x10f6f,
  0x1ec70, 0x1ecbf, 0x1ecc0, 0x1ecff, 0x1ed00, 0x1ed4f, 0x1ee00, 0x1eeff,
];

// Code points inside the blocks above (or in ASCII) that carry an explicit
// class.  Only classes reachable from a PVALID/CONTEXTJ/CONTEXTO code point
// need to be represented.
const EXPLICIT = new Map([
  [0x002d, 'ES'],
  [0x00b7, 'ON'], [0x0375, 'ON'], [0x30fb, 'ON'],
  [0x200c, 'BN'], [0x200d, 'BN'],
  [0x066b, 'AN'], [0x066c, 'AN'], [0x06dd, 'AN'], [0x08e2, 'AN'],
]);
for (let cp = 0x0030; cp <= 0x0039; cp++) EXPLICIT.set(cp, 'EN');
for (let cp = 0x0600; cp <= 0x0605; cp++) EXPLICIT.set(cp, 'AN');
for (let cp = 0x0660; cp <= 0x0669; cp++) EXPLICIT.set(cp, 'AN');
for (let cp = 0x06f0; cp <= 0x06f9; cp++) EXPLICIT.set(cp, 'EN');
for (let cp = 0x0890; cp <= 0x0891; cp++) EXPLICIT.set(cp, 'AN');
for (let cp = 0x10d30; cp <= 0x10d39; cp++) EXPLICIT.set(cp, 'AN');

/**
 * Python's `unicodedata.bidirectional(ch)`; the empty string is returned for
 * code points the local character database does not know, exactly as CPython
 * does.
 */
export function bidirectional(cp) {
  if (isCn(cp)) return '';
  const explicit = EXPLICIT.get(cp);
  if (explicit !== undefined) return explicit;
  if (isMn(cp) || isMe(cp)) return 'NSM';
  if (inRanges(cp, R_BLOCKS)) return 'R';
  if (inRanges(cp, AL_BLOCKS)) return 'AL';
