/**
 * The idna exception hierarchy.
 *
 * The nesting matters: in CPython `UnicodeError` derives from `ValueError`, and
 * idna's `check_label()` wraps its CONTEXTJ branch in `except ValueError`.  That
 * makes every CONTEXTJ failure surface as the "Unknown codepoint adjacent to
 * joiner" message rather than the "Joiner ... not allowed" one, and the port
 * reproduces that by mirroring the class relationships.
 */

/** Python's built-in `UnicodeError` (a subclass of `ValueError`). */
export class PyUnicodeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'UnicodeError';
  }
}

/** `idna.core.IDNAError` */
export class IDNAError extends PyUnicodeError {
  constructor(message) {
    super(message);
    this.name = 'IDNAError';
  }
}

/** `idna.core.IDNABidiError` */
export class IDNABidiError extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'IDNABidiError';
  }
}

/** `idna.core.InvalidCodepoint` */
export class InvalidCodepoint extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'InvalidCodepoint';
  }
}

/** `idna.core.InvalidCodepointContext` */
export class InvalidCodepointContext extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'InvalidCodepointContext';
  }
}

/** Raised where CPython would raise `UnicodeEncodeError`. */
export class PyUnicodeEncodeError extends PyUnicodeError {
  constructor(message) {
    super(message);
    this.name = 'UnicodeEncodeError';
  }
}

/** True for anything `except ValueError` would catch in CPython. */
export function isValueError(err) {
  return err instanceof PyUnicodeError || err instanceof RangeError || err instanceof TypeError;
}

