/**
 * Punycode (RFC 3492) transcoder, ported from CPython's own codec.
 *
 * The decoder in particular is *not* a plain RFC 3492 implementation: it folds
 * the extended part to upper case, tolerates a missing delimiter, and reports
 * failures in its own way.  Those quirks are visible through idna's error
 * messages, so the port follows CPython's algorithm step by step rather than
 * the RFC's.
 */

import { PyUnicodeError } from './errors.mjs';
import { toCodePoints, fromCodePoints, asciiBytes, bytesConcat, decodeAscii } from './pystr.mjs';

const DIGITS = 'abcdefghijklmnopqrstuvwxyz0123456789';

/** Punycode parameters: tmin = 1, tmax = 26, base = 36. */
function T(j, bias) {
  const res = 36 * (j + 1) - bias;
  if (res < 1) return 1;
  if (res > 26) return 26;
  return res;
}

/** 3.4 Bias adaptation; damp = 700, skew = 38. */
function adapt(delta, first, numchars) {
  delta = Math.floor(first ? delta / 700 : delta / 2);
  delta += Math.floor(delta / numchars);
  let divisions = 0;
  while (delta > 455) {
    delta = Math.floor(delta / 35); // base - tmin
    divisions += 36;
  }
  return divisions + Math.floor((36 * delta) / (delta + 38));
}

// --- encoding ---------------------------------------------------------------

/** 3.1 Basic code point segregation. */
function segregate(cps) {
  const base = [];
  const extended = new Set();
  for (const cp of cps) {
    if (cp < 128) base.push(cp);
    else extended.add(cp);
  }
  return [base, [...extended].sort((a, b) => a - b)];
}

/** Length of `cps` counting only code points below `max`. */
function selectiveLen(cps, max) {
  let res = 0;
  for (const cp of cps) if (cp < max) res += 1;
  return res;
}

/**
 * Next occurrence of `char` in `cps`: `index` counts only code points up to and
 * including `char`, `pos` is the offset in the full sequence.
 */
function selectiveFind(cps, char, index, pos) {
  const l = cps.length;
  for (;;) {
    pos += 1;
    if (pos === l) return [-1, -1];
    const c = cps[pos];
    if (c === char) return [index + 1, pos];
    if (c < char) index += 1;
  }
}

/** 3.2 Insertion unsort coding. */
function insertionUnsort(cps, extended) {
  let oldchar = 0x80;
  const result = [];
  let oldindex = -1;
  for (const char of extended) {
    let index = -1;
    let pos = -1;
    const curlen = selectiveLen(cps, char);
    let delta = (curlen + 1) * (char - oldchar);
    for (;;) {
      [index, pos] = selectiveFind(cps, char, index, pos);
      if (index === -1) break;
      delta += index - oldindex;
      result.push(delta - 1);
      oldindex = index;
      delta = 0;
    }
    oldchar = char;
  }
  return result;
}

/** 3.3 Generalized variable-length integers. */
function generateGeneralizedInteger(N, bias) {
  let result = '';
  let j = 0;
  for (;;) {
    const t = T(j, bias);
    if (N < t) return result + DIGITS[N];
    result += DIGITS[t + ((N - t) % (36 - t))];
    N = Math.floor((N - t) / (36 - t));
    j += 1;
  }
}

function generateIntegers(baselen, deltas) {
  let result = '';
  let bias = 72;
  for (let points = 0; points < deltas.length; points++) {
    const delta = deltas[points];
    result += generateGeneralizedInteger(delta, bias);
    bias = adapt(delta, points === 0, baselen + points + 1);
  }
  return result;
}

/** CPython's `str.encode('punycode')`; returns a byte array. */
export function punycodeEncode(text) {
  const cps = toCodePoints(text);
  const [base, extended] = segregate(cps);
  const deltas = insertionUnsort(cps, extended);
  const tail = asciiBytes(generateIntegers(base.length, deltas));
  const baseBytes = Uint8Array.from(base);
  if (base.length) return bytesConcat(baseBytes, asciiBytes('-'), tail);
  return tail;
}

// --- decoding ---------------------------------------------------------------

function decodeGeneralizedNumber(extended, extpos, bias) {
  let result = 0;
  let w = 1;
  let j = 0;
  for (;;) {
    if (extpos >= extended.length) {
      throw new PyUnicodeError('incomplete punicode string');
    }
    const char = extended.charCodeAt(extpos);
    extpos += 1;
    let digit;
    if (char >= 0x41 && char <= 0x5a) digit = char - 0x41; // A-Z
    else if (char >= 0x30 && char <= 0x39) digit = char - 22; // 0-9
    else {
      throw new PyUnicodeError(
        `Invalid extended code point '${extended[extpos - 1]}'`,
      );
    }
    const t = T(j, bias);
    result += digit * w;
    if (digit < t) return [extpos, result];
    w = w * (36 - t);
    j += 1;
  }
}

/** 3.2 Insertion unsort coding, decoding direction. */
function insertionSort(base, extended) {
  let char = 0x80;
  let pos = -1;
  let bias = 72;
  let extpos = 0;
  const out = toCodePoints(base);
  while (extpos < extended.length) {
    const [newpos, delta] = decodeGeneralizedNumber(extended, extpos, bias);
    pos += delta + 1;
    char += Math.floor(pos / (out.length + 1));
    if (char > 0x10ffff) {
      throw new PyUnicodeError(`Invalid character U+${char.toString(16)}`);
    }
    pos = pos % (out.length + 1);
    out.splice(pos, 0, char);
    bias = adapt(delta, extpos === 0, out.length - 1);
    extpos = newpos;
  }
  return fromCodePoints(out);
}

/** CPython's `bytes.decode('punycode')`. */
export function punycodeDecode(bytes) {
  const text = decodeAscii(bytes);
  const pos = text.lastIndexOf('-');
  let base;
  let extended;
  if (pos === -1) {
    base = '';
    extended = text.toUpperCase();
  } else {
    base = text.slice(0, pos);
    extended = text.slice(pos + 1).toUpperCase();
  }
  return insertionSort(base, extended);
}

