    const char = extended.charCodeAt(extpos);
    extpos += 1;
    let digit;
    if (char >= 0x41 && char <= 0x5a) digit = char - 0x41; // A-Z
    else if (char >= 0x30 && char <= 0x39) digit = char - 22; // 0-9
    else {
      throw new PyUnicodeError(
        `Invalid extended code point '${extended[extpos - 1]}'`,
      );
    }
    const t = T(j, bias);
    result += digit * w;
    if (digit < t) return [extpos, result];
    w = w * (36 - t);
    j += 1;
  }
}

/** 3.2 Insertion unsort coding, decoding direction. */
function insertionSort(base, extended) {
  let char = 0x80;
  let pos = -1;
  let bias = 72;
  let extpos = 0;
  const out = toCodePoints(base);
  while (extpos < extended.length) {
    const [newpos, delta] = decodeGeneralizedNumber(extended, extpos, bias);
    pos += delta + 1;
    char += Math.floor(pos / (out.length + 1));
    if (char > 0x10ffff) {
      throw new PyUnicodeError(`Invalid character U+${char.toString(16)}`);
    }
    pos = pos % (out.length + 1);
    out.splice(pos, 0, char);
    bias = adapt(delta, extpos === 0, out.length - 1);
    extpos = newpos;
  }
  return fromCodePoints(out);
}

/** CPython's `bytes.decode('punycode')`. */
export function punycodeDecode(bytes) {
  const text = decodeAscii(bytes);
  const pos = text.lastIndexOf('-');
  let base;
  let extended;
  if (pos === -1) {
    base = '';
    extended = text.toUpperCase();
  } else {
    base = text.slice(0, pos);
    extended = text.slice(pos + 1).toUpperCase();
  }
  return insertionSort(base, extended);
}

