/**
 * Port of `idna.core` -- label validation plus the `encode`/`decode` entry
 * points.
 */

import {
  toCodePoints, pyLen, encodeAscii, decodeAscii, bytesLower, bytesStartsWith,
  bytesConcat, asciiBytes,
} from './pystr.mjs';
import { reprStr, unot } from './pyrepr.mjs';
import {
  IDNAError, InvalidCodepoint, InvalidCodepointContext, PyUnicodeError, PyValueError,
} from './errors.mjs';
import { codepointClass, PVALID, CONTEXTJ, CONTEXTO, isUnknownToDatabase } from './codepoints.mjs';
import { isMark, isScript } from './unicodeprops.mjs';
import { joiningType, combiningClass, VIRAMA_COMBINING_CLASS } from './joining.mjs';
import { checkBidi } from './bidi.mjs';
import { punycodeEncode, punycodeDecode } from './punycodec.mjs';

const ALABEL_PREFIX = asciiBytes('xn--');
// FULL STOP, IDEOGRAPHIC FULL STOP, FULLWIDTH FULL STOP, HALFWIDTH IDEOGRAPHIC FULL STOP
const UNICODE_DOTS_RE = /[.。．｡]/u;

/** `idna.core.valid_label_length()` */
export function validLabelLength(label) {
  const length = typeof label === 'string' ? pyLen(label) : label.length;
  return length <= 63;
}

/** `idna.core.valid_string_length()` */
export function validStringLength(label, trailingDot) {
  const length = typeof label === 'string' ? pyLen(label) : label.length;
  return length <= (trailingDot ? 254 : 253);
}

function checkNfc(label) {
  if (label.normalize('NFC') !== label) {
    throw new IDNAError('Label must be in Normalization Form C');
  }
}

function checkHyphenOk(label) {
  const cps = toCodePoints(label);
  if (cps.length >= 4 && cps[2] === 0x2d && cps[3] === 0x2d) {
    throw new IDNAError('Label has disallowed hyphens in 3rd and 4th position');
  }
  if (cps[0] === 0x2d || cps[cps.length - 1] === 0x2d) {
    throw new IDNAError('Label must not start or end with a hyphen');
  }
}

function checkInitialCombiner(label) {
  if (isMark(toCodePoints(label)[0])) {
    throw new IDNAError('Label begins with an illegal combining character');
  }
}

/** `idna.core._combining_class()` -- raises for characters it cannot classify. */
function combiningClassOf(cp) {
  const value = combiningClass(cp);
  if (value === 0 && isUnknownToDatabase(cp)) {
    throw new PyValueError('Unknown character in unicodedata');
  }
  return value;
}

/** `idna.core.valid_contextj()` */
export function validContextj(cps, pos) {
  const cpValue = cps[pos];

  if (cpValue === 0x200c) {
    if (pos > 0 && combiningClassOf(cps[pos - 1]) === VIRAMA_COMBINING_CLASS) {
      return true;
    }

    let ok = false;
    for (let i = pos - 1; i >= 0; i--) {
      const type = joiningType(cps[i]);
      if (type === 'T') continue;
      if (type === 'L' || type === 'D') ok = true;
      break;
    }
    if (!ok) return false;

    ok = false;
    for (let i = pos + 1; i < cps.length; i++) {
      const type = joiningType(cps[i]);
      if (type === 'T') continue;
      if (type === 'R' || type === 'D') ok = true;
      break;
    }
    return ok;
  }

  if (cpValue === 0x200d) {
    if (pos > 0 && combiningClassOf(cps[pos - 1]) === VIRAMA_COMBINING_CLASS) {
      return true;
    }
    return false;
  }

  return false;
}

/** `idna.core.valid_contexto()` */
export function validContexto(cps, pos) {
  const cpValue = cps[pos];

  if (cpValue === 0x00b7) {
    if (pos > 0 && pos < cps.length - 1) {
      return cps[pos - 1] === 0x006c && cps[pos + 1] === 0x006c;
    }
    return false;
  }

  if (cpValue === 0x0375) {
    if (pos < cps.length - 1 && cps.length > 1) {
      return isScript(cps[pos + 1], 'Greek');
    }
    return false;
  }

  if (cpValue === 0x05f3 || cpValue === 0x05f4) {
    if (pos > 0) return isScript(cps[pos - 1], 'Hebrew');
    return false;
  }

  if (cpValue === 0x30fb) {
    for (const cp of cps) {
      if (cp === 0x30fb) continue;
      if (isScript(cp, 'Hiragana') || isScript(cp, 'Katakana') || isScript(cp, 'Han')) {
        return true;
      }
    }
    return false;
  }

  if (cpValue >= 0x0660 && cpValue <= 0x0669) {
    for (const cp of cps) if (cp >= 0x06f0 && cp <= 0x06f9) return false;
    return true;
  }

  if (cpValue >= 0x06f0 && cpValue <= 0x06f9) {
    for (const cp of cps) if (cp >= 0x0660 && cp <= 0x0669) return false;
    return true;
  }

  return false;
}

/** `idna.core.check_label()` */
export function checkLabel(label) {
  const cps = toCodePoints(label);
  if (cps.length === 0) throw new IDNAError('Empty Label');

  checkNfc(label);
  checkHyphenOk(label);
  checkInitialCombiner(label);

  for (let pos = 0; pos < cps.length; pos++) {
    const cpValue = cps[pos];
    const cls = codepointClass(cpValue);
    if (cls === PVALID) {
      continue;
    } else if (cls === CONTEXTJ) {
      // `IDNAError` is a `ValueError` in CPython, so the `except ValueError`
      // guard around this branch swallows the "Joiner ... not allowed" error
      // it raises itself and re-reports it as an unknown adjacent codepoint.
      try {
        if (!validContextj(cps, pos)) {
          throw new InvalidCodepointContext(
            `Joiner ${unot(cpValue)} not allowed at position ${pos + 1} in ${reprStr(label)}`,
          );
        }
      } catch (err) {
        if (err instanceof PyValueError) {
          throw new IDNAError(
            `Unknown codepoint adjacent to joiner ${unot(cpValue)} at position ${pos + 1} in ${reprStr(label)}`,
          );
        }
        throw err;
      }
    } else if (cls === CONTEXTO) {
      if (!validContexto(cps, pos)) {
        throw new InvalidCodepointContext(
          `Codepoint ${unot(cpValue)} not allowed at position ${pos + 1} in ${reprStr(label)}`,
        );
      }
    } else {
      throw new InvalidCodepoint(
        `Codepoint ${unot(cpValue)} at position ${pos + 1} of ${reprStr(label)} not allowed`,
      );
    }
  }

  checkBidi(label);
}

/** `idna.core.alabel()` -- returns the ASCII form of one label as bytes. */
export function alabel(label) {
  const asAscii = encodeAscii(label);
  if (asAscii !== null) {
    ulabel(asAscii);
    if (!validLabelLength(asAscii)) throw new IDNAError('Label too long');
    return asAscii;
  }

  checkLabel(label);
  const labelBytes = bytesConcat(ALABEL_PREFIX, punycodeEncode(label));

  if (!validLabelLength(labelBytes)) throw new IDNAError('Label too long');

  return labelBytes;
}

/** `idna.core.ulabel()` -- accepts a string or a byte array. */
export function ulabel(label) {
  let labelBytes;
  if (typeof label === 'string') {
    labelBytes = encodeAscii(label);
    if (labelBytes === null) {
      // UnicodeEncodeError: the label is already a U-label.
      checkLabel(label);
      return label;
    }
  } else {
    labelBytes = label;
  }

  labelBytes = bytesLower(labelBytes);
  if (bytesStartsWith(labelBytes, ALABEL_PREFIX)) {
    labelBytes = labelBytes.slice(ALABEL_PREFIX.length);
    if (labelBytes.length === 0) {
      throw new IDNAError('Malformed A-label, no Punycode eligible content found');
    }
    if (labelBytes[labelBytes.length - 1] === 0x2d) {
      throw new IDNAError('A-label must not end with a hyphen');
    }
  } else {
    const decoded = decodeAscii(labelBytes);
    checkLabel(decoded);
    return decoded;
  }

  let result;
  try {
    result = punycodeDecode(labelBytes);
  } catch (err) {
    if (err instanceof PyUnicodeError) throw new IDNAError('Invalid A-label');
    throw err;
  }
  checkLabel(result);
  return result;
}

function splitLabels(s, strict) {
  return strict ? s.split('.') : s.split(UNICODE_DOTS_RE);
}

/** `idna.encode()` -- returns the encoded domain as bytes. */
export function encode(s, { strict = false } = {}) {
  let trailingDot = false;
  const result = [];
  let labels = splitLabels(s, strict);
  if (labels.length === 0 || (labels.length === 1 && labels[0] === '')) {
    throw new IDNAError('Empty domain');
  }
  if (labels[labels.length - 1] === '') {
    labels = labels.slice(0, -1);
    trailingDot = true;
  }
  for (const label of labels) {
    const encoded = alabel(label);
    if (encoded.length) result.push(encoded);
    else throw new IDNAError('Empty label');
  }
  if (trailingDot) result.push(new Uint8Array(0));

  const parts = [];
  for (let i = 0; i < result.length; i++) {
    if (i) parts.push(asciiBytes('.'));
    parts.push(result[i]);
  }
  const out = bytesConcat(...parts);
  if (!validStringLength(out, trailingDot)) throw new IDNAError('Domain too long');
  return out;
}

/** `idna.decode()` -- returns the decoded domain as a string. */
export function decode(s, { strict = false } = {}) {
  let trailingDot = false;
  const result = [];
  let labels = splitLabels(s, strict);
  if (labels.length === 0 || (labels.length === 1 && labels[0] === '')) {
    throw new IDNAError('Empty domain');
  }
  if (!labels[labels.length - 1]) {
    labels = labels.slice(0, -1);
    trailingDot = true;
  }
  for (const label of labels) {
    const decoded = ulabel(label);
    if (decoded) result.push(decoded);
    else throw new IDNAError('Empty label');
  }
  if (trailingDot) result.push('');
  return result.join('.');
}

