/**
 * The slice of Python's `argparse` that this script exercises: long options with
 * `--opt value` / `--opt=value` forms, unambiguous prefix abbreviation,
 * `choices` validation, `required`, `type` coercion and the exact usage/help
 * rendering (including argparse's greedy line-wrapping at 78 columns).
 */

const TEXT_WIDTH = 78;
const PREFIX = 'usage: ';
const MAX_HELP_POSITION = 24;

/** `bool(value)` applied to a command-line string, as `type=bool` does. */
export const pyBool = (value) => value !== '';

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    this.actions = [
      { flags: ['-h', '--help'], metavar: null, help: 'show this help message and exit', isHelp: true },
    ];
  }

  addArgument(flag, { type = String, required = false, defaultValue = null, choices = null } = {}) {
    const metavar = choices
      ? `{${choices.join(',')}}`
      : flag.replace(/^--?/, '').replace(/-/g, '_').toUpperCase();
    this.actions.push({ flags: [flag], metavar, type, required, defaultValue, choices, dest: flag.replace(/^--?/, '').replace(/-/g, '_') });
    return this;
  }

  /** Rendered `[-h] --domain DOMAIN ...` fragments, in declaration order. */
  optionParts() {
    return this.actions.map((action) => {
      const invocation = action.metavar ? `${action.flags[0]} ${action.metavar}` : action.flags[0];
      return action.required ? invocation : `[${invocation}]`;
    });
  }

  formatUsage() {
    const parts = [this.prog, ...this.optionParts()];
    const indent = ' '.repeat(PREFIX.length + this.prog.length + 1);
    const lines = [];
    let line = [];
    let lineLen = PREFIX.length - 1;
    for (const part of parts) {
      if (lineLen + 1 + part.length > TEXT_WIDTH && line.length) {
        lines.push(indent + line.join(' '));
        line = [];
        lineLen = indent.length - 1;
      }
      line.push(part);
      lineLen += 1 + part.length;
    }
    if (line.length) lines.push(indent + line.join(' '));
    lines[0] = lines[0].slice(indent.length);
    return `${PREFIX}${lines.join('\n')}\n`;
  }

  formatHelp() {
    // argparse aligns help text at min(max_invocation_length + 2, 24).
    let actionMaxLength = 0;
    const invocations = this.actions.map((action) => {
      const invocation = action.isHelp
        ? action.flags.join(', ')
        : (action.metavar ? `${action.flags[0]} ${action.metavar}` : action.flags[0]);
      actionMaxLength = Math.max(actionMaxLength, invocation.length + 2);
      return invocation;
    });
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);

    let out = `${this.formatUsage()}\noptions:\n`;
    this.actions.forEach((action, i) => {
      const invocation = `  ${invocations[i]}`;
      if (!action.help) {
        out += `${invocation}\n`;
      } else if (invocation.length < helpPosition) {
        out += `${invocation.padEnd(helpPosition)}${action.help}\n`;
      } else {
        out += `${invocation}\n${' '.repeat(helpPosition)}${action.help}\n`;
      }
    });
    return out;
  }

  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /** Resolve an (optionally abbreviated) option string to a single action. */
  resolve(option) {
    const exact = this.actions.filter((a) => a.flags.includes(option));
    if (exact.length) return exact[0];
    const matches = [];
    for (const action of this.actions) {
      for (const flag of action.flags) {
        if (flag.startsWith(option)) {
          matches.push({ action, flag });
          break;
        }
      }
    }
    if (matches.length === 1) return matches[0].action;
    if (matches.length > 1) {
      const names = matches.map((m) => m.flag).join(', ');
      this.error(`ambiguous option: ${option} could match ${names}`);
    }
    return null;
  }

  parseArgs(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (!action.isHelp) namespace[action.dest] = action.defaultValue;
    }

    const seen = new Set();
    const extras = [];

    for (let i = 0; i < argv.length; i++) {
      const arg = argv[i];
      if (!arg.startsWith('-') || arg === '-' || arg === '--') {
        extras.push(arg);
        continue;
      }

      let option = arg;
      let explicitValue = null;
      const eq = arg.indexOf('=');
      if (eq !== -1) {
        option = arg.slice(0, eq);
        explicitValue = arg.slice(eq + 1);
      }

      const action = this.resolve(option);
      if (!action) {
        extras.push(arg);
        continue;
      }
      if (action.isHelp) {
        process.stdout.write(this.formatHelp());
        process.exit(0);
      }

      let raw = explicitValue;
      if (raw === null) {
        if (i + 1 >= argv.length || looksLikeOption(argv[i + 1])) {
          this.error(`argument ${action.flags[0]}: expected one argument`);
        }
        raw = argv[++i];
      }

      const value = action.type === Boolean ? pyBool(raw) : String(raw);
      if (action.choices && !action.choices.includes(value)) {
        const choices = action.choices.map((c) => `'${c}'`).join(', ');
        this.error(
          `argument ${action.flags[0]}: invalid choice: '${value}' (choose from ${choices})`,
        );
      }
      namespace[action.dest] = value;
      seen.add(action.dest);
    }

    const missing = this.actions
      .filter((a) => a.required && !seen.has(a.dest))
      .map((a) => a.flags[0]);
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

/** argparse treats `-x` as an option unless it parses as a negative number. */
function looksLikeOption(arg) {
  if (!arg.startsWith('-')) return false;
  if (arg === '-' || arg === '--') return true;
  return !/^-\d+(\.\d*)?$|^-\.\d+$/.test(arg);
}

