/**
 * Synchronous stdout/stderr writers.
 *
 * Node buffers pipe writes asynchronously, so a bare `process.stdout.write()`
 * followed by `process.exit()` can lose output.  Everything the port prints goes
 * through `fs.writeSync` to keep ordering and completeness identical to
 * Python's `print`.
 */

import { writeSync } from 'node:fs';

function writeAll(fd, text) {
  const buffer = Buffer.from(text, 'utf8');
  let offset = 0;
  while (offset < buffer.length) {
    try {
      offset += writeSync(fd, buffer, offset, buffer.length - offset);
    } catch (err) {
      if (err.code === 'EAGAIN') continue;
      if (err.code === 'EPIPE') return;
      throw err;
    }
  }
}

/** Python's `print(value)`. */
export function print(text = '') {
  writeAll(1, `${text}\n`);
}

/** Write to stderr without a trailing newline. */
export function writeStderr(text) {
  writeAll(2, text);
}

