      else out += `${invocation}\n${' '.repeat(helpPosition)}${action.help}\n`;
    });
    return out;
  }

  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /** Resolve an (optionally abbreviated) option string to a single action. */
  resolveOption(option) {
    for (const action of this.actions) {
      if (action.flags.includes(option)) return action;
    }
    const matches = [];
    for (const action of this.actions) {
      for (const flag of action.flags) {
        if (flag.startsWith(option)) {
          matches.push({ action, flag });
          break;
        }
      }
    }
    if (matches.length === 1) return matches[0].action;
    if (matches.length > 1) {
      this.error(`ambiguous option: ${option} could match ${matches.map((m) => m.flag).join(', ')}`);
    }
    return null;
  }

  parseArgs(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (!action.isHelp) namespace[action.dest] = action.defaultValue;
    }

    const seen = new Set();
    const extras = [];
    let onlyPositionals = false;

    for (let i = 0; i < argv.length; i++) {
      const arg = argv[i];
      if (onlyPositionals || !looksLikeOption(arg)) {
        if (arg === '--' && !onlyPositionals) onlyPositionals = true;
        else extras.push(arg);
        continue;
      }

      let option = arg;
      let explicitValue = null;
      const eq = arg.indexOf('=');
      if (eq !== -1) {
        option = arg.slice(0, eq);
        explicitValue = arg.slice(eq + 1);
      }

      const action = this.resolveOption(option);
      if (!action) {
        extras.push(arg);
        continue;
      }
      if (action.isHelp) {
        print(this.formatHelp().replace(/\n$/, ''));
        process.exit(0);
      }

      let raw = explicitValue;
      if (raw === null) {
        if (i + 1 >= argv.length || looksLikeOption(argv[i + 1])) {
          this.error(`argument ${action.flags[0]}: expected one argument`);
        }
        raw = argv[++i];
      }

      const value = action.type === Boolean ? pyBool(raw) : String(raw);
      if (action.choices && !action.choices.includes(value)) {
        const choices = action.choices.map((choice) => `'${choice}'`).join(', ');
        this.error(`argument ${action.flags[0]}: invalid choice: '${value}' (choose from ${choices})`);
      }
      namespace[action.dest] = value;
      seen.add(action.dest);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action.dest))
      .map((action) => action.flags[0]);
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

