import { basename } from 'node:path';

import { ArgumentParser } from './lib/argparse.mjs';
import { print, writeStderr } from './lib/pyio.mjs';
import { reprBytes } from './lib/pyrepr.mjs';
import * as idna from './lib/idna.mjs';

const parser = new ArgumentParser(basename(process.argv[1]));
parser.addArgument('--domain', { type: String, required: true });
parser.addArgument('--mode', { type: String, required: true, choices: ['encode', 'decode', 'both'] });
parser.addArgument('--transitional', { type: Boolean, required: false, defaultValue: false });
parser.addArgument('--strict', { type: Boolean, required: false, defaultValue: false });
const args = parser.parseArgs(process.argv.slice(2));

const domain = args.domain;
const mode = args.mode;
const transitional = args.transitional;
const strict = args.strict;

const firstLabel = domain.split('.')[0];

/**
 * The reference library warns once per call site when `transitional` is set.
 * Reproduced here (on stderr, like Python's `warnings`) so the observable
 * behaviour of a run matches end to end.
 */
function transitionalDeprecationWarning(line, source) {
  writeStderr(
    `test8.py:${line}: DeprecationWarning: Transitional processing has been removed `
    + 'from UTS #46. The transitional argument will be removed in a future version.\n'
    + `  ${source}\n`,
  );
}

if (mode === 'encode' || mode === 'both') {
  // 执行编码
  let encoded = null;
  try {
    if (transitional) {
      transitionalDeprecationWarning(21, 'encoded = idna.encode(domain, transitional=transitional, strict=strict)');
    }
    encoded = idna.encode(domain, { strict });
    print(reprBytes(encoded));
  } catch (err) {
    if (!(err instanceof idna.IDNAError)) throw err;
    print(`encode_error: ${err.message}`);
    encoded = null;
  }

  // 获取ULabel
  if (firstLabel && encoded) {
    try {
      if (transitional) {
        transitionalDeprecationWarning(30, 'ulabel = idna.ulabel(idna.encode(first_label, transitional=transitional, strict=strict))');
      }
      const ulabel = idna.ulabel(idna.encode(firstLabel, { strict }));
      print(ulabel);
    } catch {
      // pass
    }
  }
}

if (mode === 'decode' || mode === 'both') {
  // 执行解码（如果输入已经是编码过的）
  try {
    const decoded = idna.decode(domain, { strict });
    print(decoded);
  } catch (err) {
    if (!(err instanceof idna.IDNAError)) throw err;
    print(`decode_error: ${err.message}`);
  }
}

// 总是检查处理后的标签有效性
if (firstLabel) {
  try {
    const valid = idna.validLabelLength(firstLabel);
    print(valid ? 'True' : 'False');
  } catch {
    // pass
  }
}

