import { execFile } from 'node:child_process';

const EXE = '/workspace/dataset/test8_executable';
const JS = '/output/test8.mjs';

function run(cmd, argv) {
  return new Promise((resolve) => {
    execFile(cmd, argv, { encoding: 'utf8', maxBuffer: 1 << 24, timeout: 30000 }, (err, stdout, stderr) => {
      resolve({ stdout, code: err && typeof err.code === 'number' ? err.code : (err ? 1 : 0) });
    });
  });
}

export async function pool(items, worker, size = 12) {
  const out = new Array(items.length);
  let idx = 0;
  await Promise.all(Array.from({ length: size }, async () => {
    while (idx < items.length) {
      const i = idx++;
      out[i] = await worker(items[i], i);
    }
  }));
  return out;
}

export async function compare(cases, { verbose = false } = {}) {
  let bad = 0;
  const results = await pool(cases, async (argv) => {
    const [a, b] = await Promise.all([run(EXE, argv), run('node', [JS, ...argv])]);
    return { argv, a, b };
  });
  for (const { argv, a, b } of results) {
    if (a.stdout !== b.stdout || a.code !== b.code) {
      bad++;
      if (bad <= 40 || verbose) {
        console.log('MISMATCH', JSON.stringify(argv));
        console.log('  py  rc=' + a.code, JSON.stringify(a.stdout));
        console.log('  js  rc=' + b.code, JSON.stringify(b.stdout));
      }
    }
  }
  console.log(`${cases.length - bad}/${cases.length} matched`);
  return bad;
}

/** Expand one domain into the argv variants the script accepts. */
export function variants(domain, { modes = ['both'], stricts = [''] } = {}) {
  const out = [];
  for (const mode of modes) {
    for (const strict of stricts) {
      const argv = ['--domain', domain, '--mode', mode];
      if (strict !== '') argv.push('--strict', strict);
      out.push(argv);
    }
  }
  return out;
}

